// NewGoChunker creates a new Go AST-based chunker
func NewGoChunker() *GoChunker {
	return &GoChunker{}
}

// diagnoseZeroEdges looks up the chunks named symbol when an answer came back
// empty, and returns nil when it did not. noun reads "callers of" or
// "references from". calls counts only call edges as edge support, because
// callers answers from call edges alone; an import edge says nothing about
// whether a language's calls were indexed.
func diagnoseZeroEdges(ctx context.Context, rs semantic.RefStorage, symbol, noun string, calls bool, count int) (*zeroEdges, error) {
	if count > 0 {
		return nil, nil
	}

	langs, err := rs.SymbolLanguages(ctx, symbol)
	if err != nil {
		return nil, fmt.Errorf("failed to look up %s: %w", symbol, err)
	}
	if len(langs) == 0 {
		return &zeroEdges{
			Status:  zeroSymbolNotIndexed,
			Message: fmt.Sprintf("No %s %s: symbol not indexed, no chunk is named %s", noun, symbol, symbol),
		}, nil
	}

	// noCalls holds the languages with import or type edges but no call edges:
	// for callers they are not covered, but "records no edges" would be false.
	var withEdges, without, noCalls []string
	for _, l := range langs {
		name := l.Language
		if name == "" {
			name = "unknown language"
		}
		switch {
		case l.HasEdges && (!calls || l.HasCallEdges):
			withEdges = append(withEdges, name)
		case l.HasEdges:
			noCalls = append(noCalls, name)
		default:
			without = append(without, name)
		}
	}

	if len(withEdges) == 0 {
		kind := "edges"
		if len(noCalls) > 0 {
			kind = "call edges"
		}
		return &zeroEdges{
			Status: zeroNotIndexedForEdges,
			Message: fmt.Sprintf("No %s %s: not indexed for edges (%s is indexed as %s, and the index records no %s for it), so this does not mean none exist",
				noun, symbol, symbol, strings.Join(append(without, noCalls...), ", "), kind),
		}, nil
	}

	msg := fmt.Sprintf("No %s %s recorded in the call graph", noun, symbol)
	if len(without) > 0 {
		msg += fmt.Sprintf("; its %s chunks are not indexed for edges", strings.Join(without, ", "))
	}
	if len(noCalls) > 0 {
		msg += fmt.Sprintf("; its %s chunks record no call edges", strings.Join(noCalls, ", "))
	}
	return &zeroEdges{Status: zeroNoneRecorded, Message: msg}, nil
}

// SymbolLanguage is one language a symbol is indexed in. HasEdges counts an edge of any type, which is what refs answers from;
// HasCallEdges counts call edges only, which is what callers answers from.
type SymbolLanguage struct {
	Language     string
	HasEdges     bool
	HasCallEdges bool
}

// TestZeroCallersInALanguageWithOnlyImportEdges defends the callers wording
// for a language whose chunks record import or type edges but no call edges:
// it said "the index records no edges for it" and "its java chunks are not
// indexed for edges", both false when the index holds that language's import
// edges. callers answers from call edges, so it must say no CALL edges.
func TestZeroCallersInALanguageWithOnlyImportEdges(t *testing.T) {
	ctx := context.Background()
	storage, err := semantic.NewSQLiteStorage(filepath.Join(t.TempDir(), "semantic.db"), 4)
	if err != nil {
		t.Fatalf("NewSQLiteStorage: %v", err)
	}
	t.Cleanup(func() {
		if err := storage.Close(); err != nil {
			t.Errorf("close: %v", err)
		}
	})
	emb := []float32{0.1, 0.2, 0.3, 0.4}
	for _, c := range []semantic.Chunk{
		{ID: "java-widget", FilePath: "/r/Widget.java", Type: semantic.ChunkFunction, Name: "Widget", Language: "java"},
		{ID: "java-user", FilePath: "/r/User.java", Type: semantic.ChunkFunction, Name: "User", Language: "java"},
		{ID: "go-widget", FilePath: "/r/widget.go", Type: semantic.ChunkFunction, Name: "Gadget", Language: "go"},
		{ID: "go-caller", FilePath: "/r/caller.go", Type: semantic.ChunkFunction, Name: "Caller", Language: "go"},
	} {
		if err := storage.Create(ctx, c, emb); err != nil {
			t.Fatalf("Create %s: %v", c.ID, err)
		}
	}
	if err := storage.StoreRefs(ctx, []semantic.ChunkRef{
		{ChunkID: "java-user", RefType: semantic.RefImports, RefName: "Widget"},
		{ChunkID: "go-caller", RefType: semantic.RefCalls, RefName: "Other"},
	}); err != nil {
		t.Fatalf("StoreRefs: %v", err)
	}

	zero, err := diagnoseZeroEdges(ctx, storage, "Widget", "callers of", true, 0)
	if err != nil {
		t.Fatalf("diagnoseZeroEdges: %v", err)
	}
	if zero.Status != zeroNotIndexedForEdges {
		t.Errorf("status = %q, want %q", zero.Status, zeroNotIndexedForEdges)
	}
	if strings.Contains(zero.Message, "records no edges") || !strings.Contains(zero.Message, "records no call edges") {
		t.Errorf("message %q must say java records no call edges, not no edges", zero.Message)
	}

	// The same name in Go, which records call edges, and in Java.
	if err := storage.Create(ctx, semantic.Chunk{ID: "go-widget2", FilePath: "/r/w2.go", Type: semantic.ChunkFunction, Name: "Widget", Language: "go"}, emb); err != nil {
		t.Fatalf("Create: %v", err)
	}
	zero, err = diagnoseZeroEdges(ctx, storage, "Widget", "callers of", true, 0)
	if err != nil {
		t.Fatalf("diagnoseZeroEdges: %v", err)
	}
	if zero.Status != zeroNoneRecorded {
		t.Errorf("status = %q, want %q", zero.Status, zeroNoneRecorded)
	}
	if strings.Contains(zero.Message, "not indexed for edges") || !strings.Contains(zero.Message, "its java chunks record no call edges") {
		t.Errorf("message %q must say the java chunks record no call edges", zero.Message)
	}

	// refs counts any edge, so java's import edge is edge support there.
	zero, err = diagnoseZeroEdges(ctx, storage, "Widget", "references from", false, 0)
	if err != nil {
		t.Fatalf("diagnoseZeroEdges: %v", err)
	}
	if zero.Message != "No references from Widget recorded in the call graph" {
		t.Errorf("refs message = %q, want none recorded with no caveat", zero.Message)
	}
}

// Defends "a class does not call what its methods call" where line ranges
// alone cannot tell them apart: on one line, the class and its method span
// the same lines, and the call must still go to the method.
func TestJSRefs_OneLineClassAttributesTheCallToTheMethod(t *testing.T) {
	assertRows(t, refRows(t, "a.js", "class A { m() { go(); } }\n"), "m calls go")
}

// extractCallName extracts the function/method name from a call expression.
func extractCallName(call *ast.CallExpr) string {
	switch fn := call.Fun.(type) {
	case *ast.Ident:
		return fn.Name
	case *ast.SelectorExpr:
		if ident, ok := fn.X.(*ast.Ident); ok {
			return ident.Name + "." + fn.Sel.Name
		}
		return fn.Sel.Name
	}
	return ""
}
